                for (let x = 0; x < piece.shape[0].length; x++) {
                    rotated[x][n - 1 - y] = piece.shape[y][x];
                }
            }
            return { shape: rotated, color: piece.color };
        }

        function isValidPosition(piece, x, y) {
            for (let py = 0; py < piece.shape.length; py++) {
                for (let px = 0; px < piece.shape[py].length; px++) {
                    if (piece.shape[py][px]) {
                        const nx = x + px;
                        const ny = y + py;
                        if (nx < 0 || nx >= COLS || ny >= ROWS) return false;
                        if (ny >= 0 && board[ny][nx]) return false;
                    }
                }
            }
            return true;
        }

        function placePiece() {
            for (let py = 0; py < currentPiece.shape.length; py++) {
                for (let px = 0; px < currentPiece.shape[py].length; px++) {
                    if (currentPiece.shape[py][px]) {
                        const x = currentX + px;
                        const y = currentY + py;
                        if (y >= 0) board[y][x] = currentPiece.color;
                    }
                }
            }
        }

        function clearLines() {
            let clearedLines = 0;
            for (let y = ROWS - 1; y >= 0; y--) {
                if (board[y].every(cell => cell)) {
                    board.splice(y, 1);
                    board.unshift(Array(COLS).fill(null));
                    clearedLines++;
                    y++;
                }
            }

            if (clearedLines > 0) {
                score += clearedLines * clearedLines * 100;
                lines += clearedLines;
                level = Math.floor(lines / 10) + 1;
                dropInterval = Math.max(200, 800 - (level - 1) * 50);
            }
        }

        function spawnPiece() {
            currentPiece = getRandomPiece();
            currentX = Math.floor(COLS / 2) - 1;
            currentY = 0;

            if (!isValidPosition(currentPiece, currentX, currentY)) {
                endGame();
            }
        }

