            for (let y = 0; y < ROWS; y++) {
                for (let x = 0; x < COLS; x++) {
                    const cell = document.getElementById(`cell-${x}-${y}`);
                    cell.className = 'cell';
                    if (board[y][x]) {
                        cell.classList.add(board[y][x], 'filled');
                    }
                }
            }

            if (currentPiece) {
                for (let py = 0; py < currentPiece.shape.length; py++) {
                    for (let px = 0; px < currentPiece.shape[py].length; px++) {
                        if (currentPiece.shape[py][px]) {
                            const x = currentX + px;
                            const y = currentY + py;
                            if (y >= 0 && y < ROWS && x >= 0 && x < COLS) {
                                const cell = document.getElementById(`cell-${x}-${y}`);
                                cell.className = `cell ${currentPiece.color} filled`;
                            }
                        }
                    }
                }
            }

            scoreDisplay.textContent = score;
            levelDisplay.textContent = level;
            linesDisplay.textContent = lines;
        }

        function moveDown() {
            if (isValidPosition(currentPiece, currentX, currentY + 1)) {
                currentY++;
            } else {
                placePiece();
                clearLines();
                spawnPiece();
            }
        }

        function endGame() {
            gameRunning = false;
            gameOverScreen.classList.add('show');
            finalScoreDisplay.textContent = `최종 점수: ${score}`;
            startBtn.textContent = '다시 시작';
        }

        function toggleGame() {
            if (gameRunning) {
                gameRunning = false;
                startBtn.textContent = '게임 재개';
            } else {
                if (score === 0) {
                    board = Array(ROWS).fill(null).map(() => Array(COLS).fill(null));
                    score = 0;
                    lines = 0;
                    level = 1;
                    dropInterval = 800;
                }
                gameRunning = true;
                gameOverScreen.classList.remove('show');
                startBtn.textContent = '게임 일시정지';
                spawnPiece();
                lastDropTime = Date.now();
                gameLoop();
            }
        }

        function gameLoop() {
            if (!gameRunning) return;

            const now = Date.now();
            if (now - lastDropTime > dropInterval) {
                moveDown();
                lastDropTime = now;
            }

            updateDisplay();
            requestAnimationFrame(gameLoop);
        }

        document.addEventListener('keydown', (e) => {
            if (!gameRunning) return;

            switch(e.key) {
                case 'ArrowLeft':
                    if (isValidPosition(currentPiece, currentX - 1, currentY)) currentX--;
                    e.preventDefault();
                    break;
                case 'ArrowRight':
                    if (isValidPosition(currentPiece, currentX + 1, currentY)) currentX++;
                    e.preventDefault();
                    break;
                case 'ArrowUp':
                    const rotated = rotatePiece(currentPiece);
                    if (isValidPosition(rotated, currentX, currentY)) currentPiece = rotated;
                    e.preventDefault();
                    break;
                case 'ArrowDown':
                    moveDown();
                    e.preventDefault();
                    break;
                case ' ':
                    while (isValidPosition(currentPiece, currentX, currentY + 1)) currentY++;
                    e.preventDefault();
                    break;
            }
            updateDisplay();
        });

        createCells();
        updateDisplay();
    </script>
</body>
